class Solution {
public:
    int numSquarefulPerms(vector<int>& nums) {
        int n = nums.size();
        sort(nums.begin(), nums.end());

        auto isSquare = [](long long x) -> bool {
            if (x < 0) return false;
            long long r = (long long)sqrt((double)x);
            while (r * r > x) r--;
            while ((r + 1) * (r + 1) <= x) r++;
            return r * r == x;
        };

        vector<vector<int>> dp(1 << n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            dp[1 << i][i] = 1;
        }

        for (int mask = 1; mask < (1 << n); mask++) {
            for (int last = 0; last < n; last++) {
                if (!(mask & (1 << last))) continue;
                if (dp[mask][last] == 0) continue;
                for (int j = 0; j < n; j++) {
                    if (mask & (1 << j)) continue;
                    if (j > 0 && nums[j] == nums[j - 1] && !(mask & (1 << (j - 1)))) continue;
                    if (isSquare((long long)nums[last] + nums[j])) {
                        dp[mask | (1 << j)][j] += dp[mask][last];
                    }
                }
            }
        }

        int full = (1 << n) - 1;
        int ans = 0;
        for (int i = 0; i < n; i++) ans += dp[full][i];
        return ans;
    }
};
